class Interaction(FigmaModel):
    """
    An interaction in the Figma viewer, containing a trigger and one or more actions.
    """

    trigger: Annotated[
        Optional[
            Union[
                Trigger1,
                AfterTimeoutTrigger,
                Trigger2,
                OnKeyDownTrigger,
                OnMediaHitTrigger,
                Trigger3,
            ]
        ],
        Field(description='The user event that initiates the interaction.'),
    ]
    actions: Annotated[
        Optional[
            list[
                Union[
                    Action1,
                    OpenURLAction,
                    SetVariableAction,
                    SetVariableModeAction,
                    ConditionalAction,
                    NodeAction,
                ]
            ]
        ],
        Field(
            description='The actions that are performed when the trigger is activated.'
        ),
    ] = None


class SetVariableAction(FigmaModel):
    """
    Sets a variable to a specific value.
    """

    type: Type58
    variableId: Optional[str]
    variableValue: Optional[VariableData] = None


class ConditionalAction(FigmaModel):
    """
    Checks if a condition is met before performing certain actions by using an if/else conditional statement.
    """

    type: Type60
    conditionalBlocks: list[ConditionalBlock]


class VariableData(FigmaModel):
    """
    A value to set a variable to during prototyping.
    """

    type: Optional[VariableDataType] = None
    resolvedType: Optional[VariableResolvedDataType] = None
    value: Optional[Union[bool, float, str, RGB, RGBA, VariableAlias, Expression]] = (
        None
    )


class Expression(FigmaModel):
    """
    Defines the [Expression](https://help.figma.com/hc/en-us/articles/15253194385943) object, which contains a list of `VariableData` objects strung together by operators (`ExpressionFunction`).
    """

    expressionFunction: ExpressionFunction
    expressionArguments: list[VariableData]


class ConditionalBlock(FigmaModel):
    """
    Either the if or else conditional blocks. The if block contains a condition to check. If that condition is met then it will run those list of actions, else it will run the actions in the else block.
    """

    condition: Optional[VariableData] = None
    actions: list[
        Union[
            Action1,
            OpenURLAction,
            SetVariableAction,
            SetVariableModeAction,
            ConditionalAction,
            NodeAction,
        ]
    ]


